#!/bin/sh`nset -eu`nreward_file=/logs/verifier/reward.txt`nreport=/logs/verifier/pytest-report.json`nmkdir -p "$(dirname "$reward_file")"`nprintf '0.000\n' > "$reward_file"`ncleanup(){ code=$?; if [ "$code" -eq 0 ] && [ -s "$report" ]; then printf '1.000\n' > "$reward_file"; else printf '0.000\n' > "$reward_file"; fi; exit "$code"; }`ntrap cleanup EXIT INT TERM HUP`ntimeout 240s python3 -m pytest -q "$(dirname "$0")/test_contract.py" --junitxml="$report"`n
